from pathlib import Path
import json
S=Path(__file__).resolve().parents[1];cat=json.loads((S/'data/catalog.json').read_text('utf-8-sig'));p=S/'analysis/SuperETF.json';out=json.loads(p.read_text('utf-8-sig')) if p.exists() else {}
base={'交易成本':'每側以成交價×此百分比／100扣成本，FIFO配對扣進出兩側；不是每筆固定金額。','計算DD方式':'本策略未呼叫DoPriceTag，選每日也不會自動新增每日估值；DD隨實際配對實現。','部位管理':'固定一口為1；固定金額>0時數量=金額÷(指定換算價×商品PointValue)，可小數、不取整，金額<=0仍回1。','固定金額':'名目持倉換數量基數，不是隨淨值複利；沒有另預留交易成本，<=0退回一口。','ATR長度':'雖計算ATR均值作報表欄位，但此策略數量只用固定一口／固定金額，ATR不控制風險量，Description公式未實作。','操作方向':'固定建多或建空，影響真正下單方向；非以行情自動切換。','開始日期':'資料載入依外部傳入起訖裁切；本欄另用每根Date<起日就continue，載入函式不直接讀此欄。','結束日期':'資料載入依外部傳入起訖裁切；本欄另用每根Date>迄日就break，不等同已載資料最後根，不保證先補平。'}
cost='同一策略實例的紀錄共用FIFO，累計績效為價差扣百分比成本後乘數量，沒有再乘商品PointValue；不能直接把它當PointValue已換算的貨幣損益。執行報表另用內部entryprice算單筆，與FIFO不一定同範圍。'
def add(name,summary,family,entry,exit,mechanics,caveats,notes={}):
 iid='SuperETF/Stg'+name;ns=base|notes;out[iid]={'summary':summary,'family':family,'entry':entry,'exit':exit,'mechanics':mechanics,'caveats':caveats,'parameterNotes':{q['name']:ns[q['name']] for q in next(i for i in cat['items'] if i['id']==iid)['parameters']}}
add('SAH','按月份輪流定額建立多／空批次，持有設定月數後逐批回補，可同時保留多個月份的倉位。','月份定期持有',['起始月加組合序號×月間隔為第一排定月，之後每組合商品總數×間隔月輪一次；本商品該月第一筆資料open按固定方向新增批次。','數量按該日open換固定金額或一口，為每批排定進場月+持有月數的退出月份；不是每月重新調所有舊批次等額。'],['若當前月正好有到期批次，先用該月第一筆open退其數量，再新增當月排定新批次。','最後資料筆先全部close平，不再做當月新進；不讀固定損、停利或價格訊號。'],[cost,'每日DD會以close插入type=x的同價平開，這兩筆不收額外成本且不增加配對交易次數，內部position不改。','每批退出數量預先保存，不因價格變動重算；FIFO累計與執行報表用最後entryprice／全部舊量計部分出場的數字可不同。'],['退出月若整月缺資料，過月後沒有補執行，只能留到最後資料全平；排定進場月缺資料則直接略過該月。','持有月數0的到期安排是在當月退出檢查之後才建立，實際通常次筆同月open才退，不是同根立即退出。','進場月數間隔需>0，0讓排月份for迴圈無法推進；負值同樣不能按正常月份排程理解。'],{'開始日期':'資料載入依外部起訖裁切；SAH本欄只取年月建立排程，不逐日再裁切。','結束日期':'本欄只取年月作排定最後進場月，實際末端全平用已載資料尾，未直接按此日截止。','進場月數間隔':'每隔此月數輪到下一組合商品；本商品實際頻率=組合商品總數×此值，必須正值。','持有月數':'進場月份加此整數為到期月，只在資料月份精確相等時回補；0可變次筆資料，缺整月不順延。','計算DD方式':'每日模式持倉日close插同價免成本type=x平開以切分損益，不增加交易次數；最後全平另是正常交易。'})
add('SMS','以調整後N日前收盤作簡單動量比較，決定單商品多／空／空手，換向於下一open執行並月初重調數量。','動量與定期調倉',['N>0時今日close>按delta調整的N日前close目標多，<目標空，等於0；再用交易方向限制。不是和N日平均線比較。','方向改變才用今日close換目標數量，下一根open平舊並進新；同向期間不每天等額重算。N=0可固定只多或只空，多空都作則直接return。'],['最後資料或session改變當根close平；若不是末筆，下一open按原訊號重建，原訊號同向時保留原數量。','跨月份且當根沒有換向／換約時，以次月首open平再按同一open重算名目數量重開；退出時間卻寫前一日17:00。'],[cost,'動量參考close×當時delta／目前delta處理資料調整；成交仍用日open／close，時刻09或17由紀錄補記，不是盤中精確撮合。','ATR雖計算但數量未用；每日DD選項沒有在此核心呼叫估值。'],['月調倉的平倉價採次日open，時間卻回填前日17:00，成交時序與可知價格不一致。','程式留下new_position恰−250就改−251的特殊分支，該口數時實際空量多一，不能當成純粹固定名目。','日期截止break或動量暖機continue可在最後根強平分支前離開，因此不是所有切片都保證末筆平；N=0搭多空都作也會直接停止運算。'],{'動量長度':'0固定方向；正N比較目前close與N日前調整close，不是N日均線或報酬閾值，前N筆不交易。','交易方向':'只多／只空／雙向，限制正負動量目標；N=0且雙向不執行任何交易。','操作方向':'本類別另外宣告此欄但核心不讀，真正方向用交易方向與動量。','計算DD方式':'本核心未呼叫日估值，選每日不改交易或DD切分。'})
add('SON','只持隔夜多單：每天收盤買一筆，下一資料日開盤全賣，日間空手。','隔夜持有',['有效日先按當日open換固定金額數量，再以同日close做多；只要不是整份資料最後一筆都會建立隔夜多。'],['下一個處理日先open全平，然後當天收盤再開；整份資料最後筆只開盤出，不再收盤進。'],[cost,'數量用進場日open而成交close，固定金額不是按實際買入價精準等額；可為小數口。','方向固定只多，不使用價格、MA或ATR進場濾網，也沒有盤中停損。'],['若核心結束日期早於載入資料尾端，截止日仍可收盤進，下一根因超日期break而沒有補平；需區分整份資料末筆與指定迄日。','不檢查收盤到次開是否同合約／session，也不另作換約調整；資料源若跨約可混入價差。','每日DD模式未被讀取；隔夜損益只在下一處理日開盤退出時實現。'])
